import os,socket,struct,json,ctypes,select
from pathlib import Path

def read(fd):
 if not select.select([fd],[],[],8)[0]:raise RuntimeError('owned pipe timeout')
 return os.read(fd,65536)

def peer(conn):return list(struct.unpack('3i',conn.getsockopt(socket.SOL_SOCKET,socket.SO_PEERCRED,12)))

def bound(path,uid,gid):
 s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);s.bind(path);os.chmod(path,0o660);os.chown(path,uid,gid);return s

def run(name,expanded):
 capture_path='/probe/'+name+'-capture.sock';capture=bound(capture_path,2008,2007)
 cr,cw=os.pipe();capture_pid=os.fork()
 if capture_pid==0:
  try:
   os.close(cr);os.setgroups([]);os.setgid(2008);os.setuid(2008);capture.listen(1);capture.settimeout(8);os.write(cw,b'C')
   conn,_=capture.accept();observed=peer(conn);conn.sendall(b'C');conn.close();capture.close();os.write(cw,json.dumps({'capture_observed_gateway':observed}).encode());os._exit(0)
  except BaseException:os._exit(1)
 os.close(cw);capture.close();assert read(cr)==b'C'
 path='/probe/'+name+'-gateway.sock';listener=bound(path,2007,2005)
 rr,rw=os.pipe();gr,gw=os.pipe();out_r,out_w=os.pipe();pid=os.fork()
 if pid==0:
  try:
   os.close(rr);os.close(gw);os.close(out_r);os.close(cr)
   libc=ctypes.CDLL(None,use_errno=True)
   if libc.unshare(0x10000000)!=0:raise OSError(ctypes.get_errno(),'unshare')
   os.write(rw,b'R');os.close(rw);assert read(gr)==b'G';os.close(gr)
   os.setgroups([]);os.setgid(2007);os.setuid(2007);listener.listen(1);listener.settimeout(8);os.write(out_w,b'R')
   conn,_=listener.accept();broker_peer=peer(conn);conn.sendall(b'R');conn.close();listener.close()
   client=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);client.settimeout(8);client.connect(capture_path);capture_peer=peer(client);assert client.recv(1)==b'C';client.close()
   os.write(out_w,json.dumps({'gateway_uid':os.getuid(),'gateway_observed_broker':broker_peer,'gateway_observed_capture':capture_peer,'uid_map':Path('/proc/self/uid_map').read_text(),'gid_map':Path('/proc/self/gid_map').read_text()}).encode());os.close(out_w);os._exit(0)
  except BaseException:os._exit(1)
 os.close(rw);os.close(gr);os.close(out_w)
 try:
  assert read(rr)==b'R'
  uids=[0,2007]+([2005,2008] if expanded else [])
  Path('/proc/'+str(pid)+'/uid_map').write_text(''.join(str(i)+' '+str(i)+' 1\n' for i in sorted(uids)))
  Path('/proc/'+str(pid)+'/gid_map').write_text(''.join(str(i)+' '+str(i)+' 1\n' for i in [0,2005,2007]))
  os.write(gw,b'G');os.close(gw);gw=None;assert read(out_r)==b'R'
  br,bw=os.pipe();broker=os.fork()
  if broker==0:
   try:
    os.close(br);listener.close();os.setgroups([]);os.setgid(2005);os.setuid(2005)
    c=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);c.settimeout(8);c.connect(path);observed=peer(c);assert c.recv(1)==b'R';c.close();os.write(bw,json.dumps({'broker_observed_gateway':observed}).encode());os._exit(0)
   except BaseException:os._exit(1)
  os.close(bw);b=json.loads(read(br));os.close(br);_,bs=os.waitpid(broker,0);assert os.waitstatus_to_exitcode(bs)==0
  result=json.loads(read(out_r));_,status=os.waitpid(pid,0);assert os.waitstatus_to_exitcode(status)==0
  cp=json.loads(read(cr));_,status=os.waitpid(capture_pid,0);assert os.waitstatus_to_exitcode(status)==0
  return {'name':name,'expanded':expanded,**result,**b,**cp}
 finally:
  listener.close()
  for fd in [rr,gw,out_r,cr]:
   if fd is not None:os.close(fd)

results=[run('existing-map',False),run('reviewed-service-map',True)]
for r in results:
 assert r['gateway_uid']==2007 and r['broker_observed_gateway'][1]==2007 and r['capture_observed_gateway'][1]==2007
expected=[(65534,65534),(2005,2008)]
assert [(r['gateway_observed_broker'][1],r['gateway_observed_capture'][1]) for r in results]==expected
print(json.dumps({'schema':1,'purpose':'existing namespace bidirectional service peer-identity characterization only','results':results,'production_changes':0,'paid_calls':0,'actual_Root_or_Bifrost_runtime':False}))
